package cli

import (
	"bytes"
	"os"
	"os/exec"
	"path/filepath"
	"testing"
	"time"
)

func TestProbeEndToEndIndex(t *testing.T) {
	r := t.TempDir()
	g := func(a ...string) {
		if out, err := exec.Command("git", append([]string{"-C", r, "-c", "user.name=t", "-c", "user.email=t@t"}, a...)...).CombinedOutput(); err != nil {
			t.Fatal(a, string(out))
		}
	}
	g("init", "-q")
	os.WriteFile(filepath.Join(r, "a.txt"), []byte("x\n"), 0o644)
	t.Chdir(r)
	run := func(a ...string) {
		var o, e bytes.Buffer
		code := Main(a, &o, &e)
		tail := o.String() + e.String()
		if len(tail) > 900 {
			tail = tail[len(tail)-900:]
		}
		t.Logf("%v -> %d\n%s", a, code, tail)
	}
	run("install")
	g("add", "-A")
	g("commit", "-q", "-m", "i")
	for i, a := range [][]string{{"check", "--strict"}, {"validate", "--strict"}, {"validate", "--changed-from", "HEAD"}, {"report", "--task", "p", "--since", "HEAD"}} {
		later := time.Now().Add(time.Duration(i+2) * time.Second)
		filepath.Walk(r, func(p string, info os.FileInfo, err error) error {
			if err == nil && info.IsDir() && info.Name() == ".git" {
				return filepath.SkipDir
			}
			if err == nil && info.Mode().IsRegular() {
				os.Chtimes(p, later, later)
			}
			return nil
		})
		before, _ := os.ReadFile(filepath.Join(r, ".git", "index"))
		bi, _ := os.Stat(filepath.Join(r, ".git", "index"))
		run(a...)
		after, _ := os.ReadFile(filepath.Join(r, ".git", "index"))
		ai, _ := os.Stat(filepath.Join(r, ".git", "index"))
		t.Logf("%v index unchanged=%v mtime unchanged=%v bytes=%d", a, bytes.Equal(before, after), bi.ModTime().Equal(ai.ModTime()), len(after))
	}
}
EOF
